<?php $title='Employees'; require_once __DIR__.'/../partials/header.php'; $db=new Database(); $m=new Employee($db->getConnection()); $page=max(1,(int)($_GET['page']??1)); $q=trim($_GET['q']??''); $data=$m->all($q,$page,10); $pages=max(1,(int)ceil($data['total']/10)); ?>
<section class="panel"><div class="panel-head"><h2>Employee Directory</h2><form class="toolbar"><input class="input" name="q" value="<?=e($q)?>" placeholder="Search name, code, email..."><button class="btn btn-secondary">Search</button></form></div><div class="table-wrap"><table class="table"><thead><tr><th>Code</th><th>Employee</th><th>Department</th><th>Designation</th><th>Salary</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($data['rows'] as $r): ?><tr><td><?=e($r['employee_code'])?></td><td><strong><?=e($r['name'])?></strong><br><span class="muted"><?=e($r['email'])?></span></td><td><?=e($r['department'])?></td><td><?=e($r['designation'])?></td><td>₹<?=number_format((float)$r['basic_salary'],2)?></td><td><span class="badge <?=e($r['status'])?>"><?=e($r['status'])?></span></td><td class="actions"><a class="btn btn-secondary" href="employee-form.php?id=<?=$r['id']?>">Edit</a><form method="post" action="employee-delete.php" onsubmit="return confirm('Delete this employee? Related records will also be deleted.')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-danger" type="submit">Delete</button></form></td></tr><?php endforeach; ?><?php if(!$data['rows']): ?><tr><td colspan="7" class="empty">No employees found.</td></tr><?php endif; ?></tbody></table></div><div class="pagination"><?php for($i=1;$i<=$pages;$i++): ?><a class="<?= $i===$page?'active':''?>" href="?q=<?=urlencode($q)?>&page=<?=$i?>"><?=$i?></a><?php endfor;?></div></section>
<?php require_once __DIR__.'/../partials/footer.php'; ?>
